 ("e_units", r"\Big[\,k_x\frac{\partial^2 T}{\partial x^2}\Big]=\frac{\mathrm{W}}{\mathrm{m\,K}}\cdot\frac{\mathrm{K}}{\mathrm{m^2}}=\frac{\mathrm{W}}{\mathrm{m^3}}=[\,q_h\,]"),
 ("e_matrix", r"\left\{\dfrac{\partial}{\partial x}\quad\dfrac{\partial}{\partial y}\right\}\begin{bmatrix}k_x&0\\0&k_y\end{bmatrix}\begin{Bmatrix}\dfrac{\partial}{\partial x}\\[8pt]\dfrac{\partial}{\partial y}\end{Bmatrix}T=-q_h"),
 ("e_compact", r"\{\partial\}\,[E]\,\{\partial\}^T\,T=-q_h"),
