 ("e_nodes", r"\begin{aligned}T\big|_{x=0,\,y=0}&=a_1=\hat T_1\\T\big|_{x=a,\,y=0}&=a_1+a_2\,a=\hat T_2\\T\big|_{x=a,\,y=b}&=a_1+a_2\,a+a_3\,b+a_4\,ab=\hat T_3\\T\big|_{x=0,\,y=b}&=a_1+a_3\,b=\hat T_4\end{aligned}"),
 ("e_nodes_matrix", r"\begin{bmatrix}1&0&0&0\\1&a&0&0\\1&a&b&ab\\1&0&b&0\end{bmatrix}\begin{Bmatrix}a_1\\a_2\\a_3\\a_4\end{Bmatrix}=\begin{Bmatrix}\hat T_1\\\hat T_2\\\hat T_3\\\hat T_4\end{Bmatrix}"),
 ("e_coeffs", r"a_1=\hat T_1,\qquad a_2=\frac{-\hat T_1+\hat T_2}{a},\qquad a_3=\frac{-\hat T_1+\hat T_4}{b},\qquad a_4=\frac{\hat T_1-\hat T_2+\hat T_3-\hat T_4}{a\,b}"),
 ("e_collect", r"T(x,y)=\left(\frac{(a-x)(b-y)}{ab}\right)\hat T_1+\left(\frac{x\,(b-y)}{ab}\right)\hat T_2+\left(\frac{x\,y}{ab}\right)\hat T_3+\left(\frac{y\,(a-x)}{ab}\right)\hat T_4"),
 ("e_shape", r"N_1=\frac{(a-x)(b-y)}{ab},\qquad N_2=\frac{x\,(b-y)}{ab},\qquad N_3=\frac{x\,y}{ab},\qquad N_4=\frac{y\,(a-x)}{ab}"),
 ("e_T_N", r"T=N_1\hat T_1+N_2\hat T_2+N_3\hat T_3+N_4\hat T_4=\{N\}\{\hat T\}^T"),
