 ("e_kron", r"N_i(x_j,y_j)=\delta_{ij}=\begin{cases}1,&i=j\\0,&i\neq j\end{cases}"),
 ("e_pou", r"\sum_{i=1}^{4}N_i=1\quad\text{everywhere in the element}"),
