 ("e_k_preview", r"\begin{aligned}{}[k]&=\int_x\!\int_y\{N\}^T\{\partial\}[E]\{\partial\}^T\{N\}\,dy\,dx\\[4pt]{}[k]\{\hat T\}^T&=\{q\}+\{b\}=\{r\}\end{aligned}"),
 ("e_act5_dN", r"\frac{\partial N_i}{\partial x}=\frac{1}{ab}\big\{-(b-y),\ (b-y),\ y,\ -y\big\}=\big\{-0.35,\ 0.35,\ 0.15,\ -0.15\big\}"),
 ("e_act5_grad", r"\begin{aligned}\frac{\partial T}{\partial x}&=\sum_i\frac{\partial N_i}{\partial x}\hat T_i=-0.35(100)+0.35(140)+0.15(160)-0.15(120)\\&=-35+49+24-18=20\ \mathrm{K\,m^{-1}}\end{aligned}"),
 ("e_act5_q", r"q_x=-k_x\frac{\partial T}{\partial x}=-(2)(20)=-40\ \mathrm{W\,m^{-2}}"),
