 ("e_poly8", r"T=a_1+a_2x+a_3y+a_4x^2+a_5y^2+a_6xy+a_7x^2y+a_8xy^2"),
 ("e_N8", r"\{N\}=\{x\}\,[\,x|\,]^{-1},\qquad\text{e.g. } N_5=\frac{4\,x\,(a-x)(b-y)}{a^2\,b}"),
 ("e_exit3", r"\{\partial\}[E]\{\partial\}^T T=-q_h\ \ \text{with}\ k_x=k_y=k"),
 ("e_cent", r"N_i\Big(\tfrac{a}{2},\tfrac{b}{2}\Big)=\frac{(a/2)(b/2)}{ab}=\frac14\quad\text{for every } i"),
